select json_build_object('active',(select count(*) from raw_items where section='meat' and merged_into is null and not hidden),'cats',(select json_agg(x) from (select coalesce(nullif(nutrient,''),'(none)') c,count(*) n from raw_items where section='meat' and merged_into is null and not hidden group by 1 order by 2 desc) x),'nocat',(select json_agg(name) from raw_items where section='meat' and merged_into is null and not hidden and coalesce(nutrient,'')=''),'coded',(select json_agg(code||' '||name) from raw_items where code is not null and merged_into is null)) r;
